start, end = 51317, 89717
# prepare events in window
evs = [e for e in events if start <= e[2] <= end]
print('events_in_window', len(evs))
# relevant events
rel = [e for e in evs if e[0] in (1010,883) or e[1] in (1010,883)]
print('relevant_count', len(rel))
for e in rel:
    print(e)
# build outgoing mapping
out = {}
for u,v,t in evs:
    out.setdefault(u, []).append((t,v))
for u in out:
    out[u].sort()
# start states: events where u==1010
starts = out.get(1010, [])
print('starts_count', len(starts))
for s in starts:
    print('start_event', 1010, '->', s[1], s[0])

# BFS over states (node, time)
from collections import deque
from bisect import bisect_right
start_states = [(v,t) for (t,v) in starts]
q = deque(start_states)
visited = set(start_states)
parent = {}
found_state = None
while q:
    node, t = q.popleft()
    if node == 883:
        found_state = (node,t)
        break
    lst = out.get(node, [])
    times = [it[0] for it in lst]
    i = bisect_right(times, t)
    while i < len(lst) and lst[i][0] - t <= 600:
        t2, v2 = lst[i]
        state = (v2, t2)
        if state not in visited:
            visited.add(state)
            parent[state] = (node,t)
            q.append(state)
        i += 1

if found_state is None:
    print('no_time_respecting_path_found')
else:
    # reconstruct path
    path = []
    cur = found_state
    while cur in parent or cur in start_states:
        path.append(cur)
        if cur in start_states:
            break
        cur = parent[cur]
    path.reverse()
    print('path_length', len(path))
    for node,t in path:
        print(node, t)

# Additionally, print outgoing events from 66 between 70407+1 and 70407+600
if starts:
    for (t,v) in starts:
        if v==66:
            start_t = t
            lst = out.get(66,[])
            for (t2,v2) in lst:
                if t2>start_t and t2 - start_t <=600:
                    print('66_out', t2, '->', v2)

# Also check 2-hop path: 1010->66 at 70407 -> X at t1 within 600 -> 883 at 70983 within 600 of t1
# find any X where 66->X at t1 and t1<=70983 and 70983-t1<=600
three_targets = [t for (u,v,t) in evs if v==883]
print('incoming_883_times_sample', three_targets[:10])
for incoming_time in three_targets:
    # look for possible predecessors
    candidates = []
    for (t1,v1) in out.get(66,[]):
        if t1>70407 and t1 - 70407 <=600:
            if incoming_time > t1 and incoming_time - t1 <=600:
                candidates.append((t1,v1,incoming_time))
    if candidates:
        print('candidates for incoming', incoming_time, candidates)

# print some of visited states count
print('visited_states_count', len(visited))
